missing = [
    package_name
    for module_name, package_name in REQUIRED_LIBRARIES.items()
    if importlib.util.find_spec(module_name) is None
]

if missing:
    print("\n[!] Missing libraries:\n")

    for library in missing:
        print(f"    • {library}")

    print()
    sys.exit(1)


