    def open_rename_window_Listener_Change(self):
        selected = self.session_table_listener.selection()
        if not selected:
            messagebox.showwarning("No Selection", "Please select a beacon to rename.")
            return

        row_id = selected[0]

        if self.rename_Listener_Change and self.rename_Listener_Change.winfo_exists():  
            self.rename_Listener_Change.lift()  
            return         

        self.rename_Listener_Change = tk.Toplevel(self.Session_Manager)
        self.rename_Listener_Change.title("Rename Listener")
        self.rename_Listener_Change.resizable(False, False)

        self.rename_Listener_Change.withdraw()
        self.center_window(self.rename_Listener_Change, 300, 140)
        self.rename_Listener_Change.deiconify()

        self.rename_Listener_Change.transient(self.Session_Manager)  
        self.rename_Listener_Change.lift()

        tk.Label(self.rename_Listener_Change, text="Enter New Listener Name:").pack(pady=10)

        self.listener_name_entry = tk.Entry(self.rename_Listener_Change, width=30, bg="#3E3E3E", fg="white", insertbackground="#730f06", selectbackground="#730f06")
        self.listener_name_entry.pack(pady=5)
        self.listener_name_entry.focus_force()
        error_label_ufw = tk.Label(self.rename_Listener_Change, text="", foreground="red")
        error_label_ufw.pack()
        self.create_context_menu(self.listener_name_entry)

        def save_name_Change():
            listener_name = self.listener_name_entry.get().strip()
            if not listener_name:
                error_label_ufw.config(text="Name cannot be empty.")
                return

            if listener_name in self.listener_names:
                error_label_ufw.config(text="This name is already used.")
                return

            current_values = list(self.session_table_listener.item(row_id, "values"))
            old_name = current_values[0]
            current_values[0] = listener_name
            self.session_table_listener.item(row_id, values=current_values)

            if old_name in self.listener_names:
                self.listener_names.remove(old_name)
            self.listener_names.append(listener_name)

            if hasattr(self, "saved_sessions"):
                for i, session in enumerate(self.saved_sessions):
                    if session[0] == old_name:
                        self.saved_sessions[i][0] = listener_name
                        break
            self.rename_Listener_Change.destroy()

        tk.Button(self.rename_Listener_Change, text="Save", command=save_name_Change, bg='#730f06', fg='white', width=10,activebackground="#9A1105",).pack()

