        sess = self.doh_listener_instance.sessions[session_id]
        parts = self.doh_listener_instance.split_command_safe(command.strip())
        
        sess["pending_command_parts"] = parts
        sess["sent_parts_count"] = 0
        sess["command_checksum"] = hashlib.sha256(command.encode('utf-8')).hexdigest()[:8]
