    def create_checkbox(self, parent, text, variable):
        frame = tk.Frame(parent, bg="#0f1110")
        frame.pack(anchor="w", pady=3, fill=tk.X)
        
        checkbox_label = tk.Label(frame, bg="#0f1110", cursor="hand2")
        checkbox_label.pack(side=tk.LEFT)
        
        text_label = tk.Label(frame, text=text, bg="#0f1110", fg="#888888")
        text_label.pack(side=tk.LEFT, padx=(5, 0))
        
        def update_state():
            if variable.get():
                checkbox_label.config(
                    image=self.checkbox_checked_icon
                )
                text_label.config(fg="white")
            else:
                checkbox_label.config(
                    image=self.checkbox_unchecked_icon
                )
                text_label.config(fg="#888888")


        def toggle(event=None):
            variable.set(not variable.get())
            update_state()


        checkbox_label.bind("<Button-1>", toggle)
        text_label.bind("<Button-1>", toggle)

        update_state()
 
    def center_window(self, window, width, height):
        screen_width = window.winfo_screenwidth()
        screen_height = window.winfo_screenheight()
        x = (screen_width - width) // 2
        y = (screen_height - height) // 2
        window.geometry(f"{width}x{height}+{x}+{y}")
 
    def log_message_Obfuscator(self, message, msg_type="info"):
        self.log_text.configure(state='normal')
        colors = {'info': "yellow", 'success': "yellow", 'warning': "#ff0000", 'error': "#ff0000"}
        color = colors.get(msg_type, '#888888')
        self.log_text.insert(tk.END, f" {message}\n", msg_type)
        self.log_text.tag_config(msg_type, foreground=color)
        self.log_text.see(tk.END)
        self.log_text.configure(state='disabled')
 
