    def random_id(self, length=8):
        return ''.join(random.choices(string.ascii_lowercase + string.digits, k=length))
 
    def random_var_name(self):
        prefixes = ['var', 'tmp', 'obj', 'data', 'val', 'item', 'ref', 'ptr']
        return f"{random.choice(prefixes)}_{self.random_id(6)}"
 
    def write_file(self, filename, content):
        try:
            with open(filename, 'w', encoding='utf-8', errors="ignore") as f:
                f.write(content)
            return True
        except Exception as e:
            self.log_message_Obfuscator(f"Failed to write file: {str(e)}", "error")
            return False
 
    def xor_encrypt(self, data, key):
        return bytes([b ^ key[i % len(key)] for i, b in enumerate(data)])
 
    def generate_xor_key(self, length=16):
        return bytes([random.randint(1, 255) for _ in range(length)])
 
    def xor_encrypt_content(self, content, language='py'):
        key = self.generate_xor_key()
        key_hex = key.hex()
        if isinstance(content, str):
            content_bytes = content.encode('utf-8')
        else:
            content_bytes = content
        encrypted = self.xor_encrypt(content_bytes, key)
        encrypted_b64 = base64.b64encode(encrypted).decode('utf-8')
        return encrypted_b64, key_hex, key
 
    def obfuscate_python(self, content):
        if self.options['xor_encryption'].get():
            return self.obfuscate_python_xor(content)
        try:
            compressed = zlib.compress(content.encode("utf-8"))
            encoded = base64.b64encode(compressed).decode("utf-8")
            result = 'import zlib,base64' + chr(10) + 'exec(zlib.decompress(base64.b64decode(' + repr(encoded) + ')).decode("utf-8"))'
            compile(result, '<string>', 'exec')
            return result
        except:
            return content
 
