            encrypted_hex = encrypted.hex()
            
            result = 'key=bytes.fromhex(' + repr(key_hex) + ')' + chr(10) + 'enc=bytes.fromhex(' + repr(encrypted_hex) + ')' + chr(10) + 'exec(bytes([b^key[i%len(key)]for i,b in enumerate(enc)]).decode("utf-8"))'
