    def validate_teams_inputs(self, tenant_id, client_id, client_secret, team_id, channel_id, listener_name):
        if not tenant_id:
            return "Tenant ID cannot be empty"
        if len(tenant_id) < 10:
            return "Tenant ID appears to be invalid (too short)"
        
        if not client_id:
            return "Client ID cannot be empty"
        if len(client_id) < 10:
            return "Client ID appears to be invalid (too short)"
        
        if not client_secret:
            return "Client Secret cannot be empty"
        if len(client_secret) < 10:
            return "Client Secret appears to be invalid (too short)"
        
        if not team_id:
            return "Team ID cannot be empty"
        try:
            team_id_int = int(team_id)
            if team_id_int <= 0:
                return "Team ID must be a positive number"
        except ValueError:
            return "Team ID must be a valid number"
        
        if not channel_id:
            return "Channel ID cannot be empty"
        try:
            channel_id_int = int(channel_id)
            if channel_id_int <= 0:
                return "Channel ID must be a positive number"
        except ValueError:
            return "Channel ID must be a valid number"
        
        if not listener_name:
            return "Listener Name cannot be empty"
        listener_name = listener_name.strip()
        if len(listener_name) < 2:
            return "Listener Name must be at least 2 characters"
        if len(listener_name) > 50:
            return "Listener Name cannot exceed 50 characters"
        
        return None

    def save_and_connect_teams(self):
        tenant_id = self.tenant_id_entry.get().strip()
        client_id = self.client_id_entry.get().strip()
        client_secret = self.client_secret_entry.get().strip()
        team_id = self.team_id_entry.get().strip()
        channel_id = self.channel_id_entry_teams.get().strip()
        listener_name = self.listener_name_entry_teams.get().strip()
        window_agent = self.window_teams

        error = self.validate_teams_inputs(tenant_id, client_id, client_secret, team_id, channel_id, listener_name)
        if error:
            messagebox.showerror("Validation Error", error, parent=self.window_teams)
            return
        
        can_connect, message = self.session_manager_teams.can_connect(tenant_id, client_id, client_secret, team_id, channel_id, window_agent)
        if not can_connect:
            messagebox.showerror("Connection Error", message, parent=self.window_teams)
            return
        
        self.tenant_id = tenant_id
        self.client_id = client_id
        self.client_secret = client_secret
        self.team_id = team_id
        self.channel_id_teams = channel_id
        
        exfiltration_profile = self.exfiltration_profile_var.get()
        hidden_addresses = self.hidden_addresses
        listener_uuid = str(uuid.uuid4())
        values = [listener_name, "Teams Channel", "Graph API", "TLS 1.3", "Teams Agent", "Active", tenant_id, channel_id]

        if not hasattr(self, "saved_sessions"):
            self.saved_sessions = []
        self.saved_sessions.append(values)

        try:
            self.session_table_listener.insert("", "end", values=values)
        except Exception:
            pass
        
        server = Teams_Agent(self.center_window, self.create_context_menu, self.save_screenshot_window,
                            self.open_file_browse_window, self.save_file_from_browse,
                            exfiltration_profile, hidden_addresses, self.update_output_text,
                            self.add_session, listener_uuid, self.windows_os_icon,
                            self.linux_os_icon, self.session_table, tenant_id, client_id,
                            client_secret, team_id, channel_id, self.session_manager_teams,
                            listener_name)
        
        self.teams_agents.append(server)
        self.running_server_instances[listener_uuid] = server
        threading.Thread(target=server.start_connection, daemon=True).start()
        self.window_teams.destroy()

        
