        self.total_accepted_sessions = 0
        self.current_active_sessions = 0
        self.auth_timeout_enabled = auth_timeout_enabled
        self.lock = threading.Lock()
        self.base64_img_windows = icon_windows
        self.hidden_addresses = hidden_addresses
        self.base64_img_linux = icon_linux
