                if decrypted_text == "pong":
                    with self.lock:
                        if session_id in self.active_sessions:
                            self.active_sessions[session_id]["last_seen"] = time.time()
                    continue
                
                if decrypted_text:
                    self.execution_status[session_id] = False
                
