        self.auth_timeout_enabled = auth_timeout_enabled
        self.max_sessions_limit = max_total_sessions
        self.total_accepted_sessions = 0
        self.current_active_sessions = 0
        self.hidden_addresses = hidden_addresses
        self.base64_img_windows = icon_windows
        self.base64_img_linux = icon_linux


        self.config = QuicConfiguration(is_client=False)
        self.https_cert =https_cert
        self.listener_uuid = listener_uuid
        self.ja3s_enabled = ja3s_enabled


        self.selected_cert_file = selected_cert_file
        self.selected_key_file = selected_key_file
